 def InsertionSort():
      global Jobs
      global NumberOfJobs
      for I in range(1, NumberOfJobs):
           Current1 = Jobs[I][0]
           Current2 = Jobs[I][1]
           while I > 0 and Jobs[I-1][1] > Current2:
                Jobs[I][0] = Jobs[I-1][0]
                Jobs[I][1] = Jobs[I-1][1]
                I = I - 1
           Jobs[I][0] = Current1
           Jobs[I][1] = Current2
 Java
 public static void InsertionSort(){
        Integer Current1;
        Integer Current2;
        Integer Counter;
        Integer Placed;
        for(Integer i = 1; i < NumberOfJobs; i++){
              Current1 = Jobs[i][0];
              Current2 = Jobs[i][1];
              while(i > 0 && Jobs[i-1][1] > Current2){
                     Jobs[i][0] = Jobs[i-1][0];
                     Jobs[i][1] = Jobs[i-1][1];
                     i = i - 1;
              }
              Jobs[i][0] = Current1;
              Jobs[i][1] = Current2;
        }
 }
 VB.NET
 Sub InsertionSort()
     Dim Tempa As Integer
     Dim Tempb As Integer
     Dim Counter As Integer
     Dim Placed As Boolean
     For i = 1 To NumberOfJobs - 1
          Tempa = Jobs(i, 0)
          Tempb = Jobs(i, 1)
          Counter = i
          Placed = False
          While (Counter > 0 And Not Placed)
               If (Jobs(Counter - 1, 1) > Tempb) Then
                   Jobs(Counter, 0) = Jobs(Counter - 1, 0)
                   Jobs(Counter, 1) = Jobs(Counter - 1, 1)
                   Counter = Counter - 1
               Else
                   Placed = True
               End If
          End While
          Jobs(Counter, 0) = Tempa
          Jobs(Counter, 1) = Tempb
     Next i
 End Sub

